              </button>
              <button 
                onClick={() => setGeneratedQR(null)}
                className="w-full py-3 text-slate-400 hover:text-white font-medium"
              >
                New Pre-Registration
              </button>
            </div>
          </div>
        </div>
      </div>
    );
